<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('supervisor');
$q=db()->prepare("SELECT DISTINCT s.id,s.matric_number,s.first_name,s.last_name,s.profile_complete,s.email,s.phone,f.name faculty,d.name department,p.name programme,COALESCE(pr.title,'No project registered yet') project_title FROM users s JOIN roles sr ON sr.id=s.role_id LEFT JOIN departments d ON d.id=s.department_id LEFT JOIN faculties f ON f.id=d.faculty_id LEFT JOIN programmes p ON p.id=s.programme_id LEFT JOIN student_supervisors ss ON ss.student_id=s.id AND ss.supervisor_id=? AND ss.ended_at IS NULL LEFT JOIN project_members pm ON pm.student_id=s.id LEFT JOIN projects pr ON pr.id=pm.project_id LEFT JOIN project_supervisors ps ON ps.project_id=pr.id AND ps.supervisor_id=? AND ps.ended_at IS NULL WHERE sr.name='student' AND (ss.id IS NOT NULL OR ps.id IS NOT NULL) ORDER BY s.last_name,s.first_name");$q->execute([$u['id'],$u['id']]);$students=$q->fetchAll();$pageTitle='My Assigned Students';$crumbTrail=['Students'];require dirname(__DIR__).'/includes/header.php';
?>
<section class="card filter-bar mb-3"><div class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input type="search" class="form-control" placeholder="Search students..." aria-label="Search students" data-live-filter="#studentsTable tbody tr"></label></div></section>
<section class="card p-4"><div class="section-row mb-3"><h2 class="section-heading mb-0">Assigned Students</h2><span class="text-muted small"><?= count($students) ?> students</span></div><div class="table-responsive"><table class="table table-soft align-middle" id="studentsTable"><thead><tr><th>Student</th><th>Academic registration</th><th>Project</th><th>Contact</th></tr></thead><tbody>
<?php foreach($students as $s): $nm=trim(($s['first_name']??'').' '.($s['last_name']??'')); ?><tr><td><div class="person"><span class="person-avatar"><?= e(ui_initials($nm?:'S')) ?></span><div><strong><?= e($nm?:'Profile awaiting completion') ?></strong><small><?= e($s['matric_number']) ?></small></div></div></td><td><?= e($s['faculty']??'—') ?><br><small class="text-muted"><?= e($s['department']??'—') ?> · <?= e($s['programme']??'—') ?></small></td><td class="fw-bold"><?= e($s['project_title']) ?></td><td><?= e($s['email']??'—') ?><br><small class="text-muted"><?= e($s['phone']??'') ?></small></td></tr><?php endforeach; ?>
<?php if(!$students): ?><tr><td colspan="4"><div class="empty-state">No students have been assigned yet.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
